<?php
if (!defined('ABSPATH')) { exit; }
global $wp_query;$state=vibelab_v2_search_current();
if (!$state) { require __DIR__.'/index.php'; return; }
$total=(int)$wp_query->found_posts;$first=$total?($state['paged']-1)*9+1:0;$last=$total?min($state['paged']*9, $total):0;
$filterCount=($state['category']!==''?1:0)+count($state['need'])+count($state['tool'])+($state['status']!==''?1:0);
$activeCount=$filterCount+($state['s']!==''?1:0);
$clear=vibelab_v2_search_url($state, array('s'=>'', 'category'=>'', 'need'=>array(), 'tool'=>array(), 'status'=>'', 'sort'=>'name'));
get_header();
?>
<main id="main" tabindex="-1"><div class="v2-shell">
<?php vibelab_v2_breadcrumb(array(array('', 'Tìm tài nguyên'))); ?>
<header class="v2-search-header"><div><h1><?php echo $state['s']!==''?'Kết quả cho “'.esc_html($state['s']).'”':'Tìm tài nguyên'; ?></h1><p>Tìm theo việc cần làm, sau đó đọc tình trạng và điều kiện trước khi chọn.</p></div>
<form class="v2-search-lead" action="<?php echo esc_url(home_url('/')); ?>" method="get" role="search"><input type="hidden" name="vne_find" value="1"><input type="hidden" name="scope" value="resources"><label for="v2-search-query">Bạn muốn làm việc gì?</label><div><input id="v2-search-query" name="s" type="search" value="<?php echo esc_attr($state['s']); ?>" placeholder="Ví dụ: tạo website Astro"><button type="submit">Tìm tài nguyên</button></div></form></header>
<div class="v2-search-layout"><aside>
<details class="v2-filter-panel"><summary>Bộ lọc<?php echo $filterCount?' ('.(int)$filterCount.')':''; ?></summary><div class="v2-filter-body"><form method="get" action="<?php echo esc_url(home_url('/')); ?>">
<?php vibelab_v2_search_hidden($state, array('category', 'need', 'tool', 'status')); ?>
<label for="v2-filter-category">Danh mục</label><select id="v2-filter-category" name="category"><option value="">Tất cả danh mục</option><?php foreach ($state['options']['category'] as $slug=>$row) { ?><option value="<?php echo esc_attr($slug); ?>" <?php selected($state['category'], $slug); ?>><?php echo esc_html($row['term']->name).' ('.(int)$row['count'].')'; ?></option><?php } ?></select>
<?php foreach (array('need'=>'Bạn muốn làm gì?', 'tool'=>'Công cụ') as $key=>$label) { ?><fieldset><legend><?php echo esc_html($label); ?></legend><?php if (!$state['options'][$key]) { ?><p>Chưa có lựa chọn.</p><?php } foreach ($state['options'][$key] as $slug=>$row) { ?><label><input type="checkbox" name="<?php echo esc_attr($key); ?>[]" value="<?php echo esc_attr($slug); ?>" <?php checked(in_array($slug, $state[$key], true)); ?>><span><?php echo esc_html($row['term']->name); ?></span><small><?php echo (int)$row['count']; ?></small></label><?php } ?></fieldset><?php } ?>
<fieldset><legend>Tình trạng</legend><?php foreach ($state['options']['status'] as $value=>$row) { ?><label><input type="radio" name="status" value="<?php echo esc_attr($value); ?>" <?php checked($state['status'], $value); ?>><span><?php echo esc_html($row['label']); ?></span><small><?php echo (int)$row['count']; ?></small></label><?php } ?></fieldset>
<p class="v2-filter-help">Các nhóm khác nhau được áp dụng đồng thời. Tình trạng chỉ là chỉ dẫn; hãy đọc hồ sơ chi tiết trước khi dùng.</p><button class="v2-button" type="submit">Áp dụng bộ lọc</button><?php if ($activeCount) { ?><a class="v2-filter-clear" href="<?php echo esc_url($clear); ?>">Xóa tất cả</a><?php } ?>
</form></div></details></aside>
<section aria-label="Kết quả tìm kiếm"><div class="v2-search-toolbar"><p role="status"><?php echo $state['errors']?'Chưa thể hiển thị kết quả':($total?'Hiển thị '.(int)$first.'–'.(int)$last.' trong '.(int)$total.' tài nguyên':'0 tài nguyên'); ?></p><form method="get" action="<?php echo esc_url(home_url('/')); ?>"><?php vibelab_v2_search_hidden($state, array('sort')); ?><label for="v2-search-sort">Sắp xếp</label><select id="v2-search-sort" name="sort"><?php $sorts=array('name'=>'Tên A–Z', 'name_desc'=>'Tên Z–A', 'observed'=>'Đối chiếu gần nhất');if ($state['s']!=='') {$sorts=array('relevance'=>'Phù hợp từ khóa')+$sorts;}foreach ($sorts as $value=>$label) { ?><option value="<?php echo esc_attr($value); ?>" <?php selected($state['sort'], $value); ?>><?php echo esc_html($label); ?></option><?php } ?></select><button type="submit">Sắp xếp</button></form></div>
<?php if ($activeCount) { ?><nav class="v2-active-filters" aria-label="Tiêu chí đang áp dụng"><?php if ($state['s']!=='') { ?><a href="<?php echo esc_url(vibelab_v2_search_url($state, array('s'=>''))); ?>">Từ khóa: <?php echo esc_html($state['s']); ?><span aria-hidden="true"> ×</span></a><?php } if ($state['category']!=='' && isset($state['options']['category'][$state['category']])) { ?><a href="<?php echo esc_url(vibelab_v2_search_url($state, array('category'=>''))); ?>"><?php echo esc_html($state['options']['category'][$state['category']]['term']->name); ?><span aria-hidden="true"> ×</span></a><?php } foreach (array('need', 'tool') as $key) { foreach ($state[$key] as $slug) { $row=$state['options'][$key][$slug]; ?><a href="<?php echo esc_url(vibelab_v2_search_url($state, array($key=>array_values(array_diff($state[$key], array($slug)))))); ?>"><?php echo esc_html($row['term']->name); ?><span aria-hidden="true"> ×</span></a><?php }} if ($state['status']!=='') { ?><a href="<?php echo esc_url(vibelab_v2_search_url($state, array('status'=>''))); ?>"><?php echo esc_html($state['options']['status'][$state['status']]['label']); ?><span aria-hidden="true"> ×</span></a><?php } ?><a class="v2-clear-all" href="<?php echo esc_url($clear); ?>">Xóa tất cả</a></nav><?php } ?>
<?php if (!vibelab_v2_contract_status()['ready']) { ?><div class="v2-empty" role="alert"><h2>Thư viện chưa sẵn sàng</h2><p>Chưa thể tìm kiếm lúc này. Hãy thử lại sau.</p></div>
<?php } elseif ($state['errors']) { ?><div class="v2-empty" role="alert"><h2>Chưa áp dụng được tiêu chí</h2><ul><?php foreach ($state['errors'] as $error) { ?><li><?php echo esc_html($error); ?></li><?php } ?></ul><a href="<?php echo esc_url($clear); ?>">Đặt lại tìm kiếm</a></div>
<?php } elseif ($total) { ?><div class="v2-resource-list"><?php $index=$first;while (have_posts()) { the_post();$item=vne_library_item(get_the_ID());if (!is_wp_error($item)&&!empty($item['derived']['is_public'])) { vibelab_v2_resource_row($item, $index++); } } ?></div><?php vibelab_v2_search_pagination($state); ?>
<?php } else { ?><div class="v2-empty"><h2>Chưa có kết quả phù hợp</h2><p>Thử từ khóa ngắn hơn hoặc bỏ bớt một bộ lọc.</p><a class="v2-button" href="<?php echo esc_url($clear); ?>">Xóa tất cả tiêu chí</a><a href="<?php echo esc_url(vibelab_v2_archive_url('vne_resource')); ?>">Khám phá toàn bộ thư viện</a></div><?php } ?>
</section></div></div></main>
<?php get_footer(); ?>
